-- chair-step: inverse of read_lane_v2_b2_34_agent_cmp_response_feedback — un-enrolls agent.cmp_response_feedback from read-lane v2 and regenerates it back to the set-form read lane.
delete from iam.read_lane_v2_rollout where token = (select token from platform.entity_types where schema_name = 'agent' and table_name = 'cmp_response_feedback' and is_active);
select iam.apply_rls('agent', 'cmp_response_feedback', (select token from platform.entity_types where schema_name = 'agent' and table_name = 'cmp_response_feedback' and is_active), (select rls_variant from platform.entity_types where schema_name = 'agent' and table_name = 'cmp_response_feedback' and is_active));
